 1	'use strict';
 2	// 服务端渲染页面（PC-05/06/09/15）。所有用户文本经 htmlEscape；内联 JSON 经 jsonForScript。
 3	const { htmlEscape, jsonForScript } = require('./escape');
 4	
 5	const POLL_INTERVAL_MS = 3000;
 6	
 7	function layout(title, body) {
 8	  return `<!doctype html><html lang="zh"><head><meta charset="utf-8">` +
 9	    `<meta name="viewport" content="width=device-width,initial-scale=1">` +
10	    `<title>${htmlEscape(title)}</title></head><body>${body}</body></html>`;
11	}
12	
13	function closedBanner(poll) {
14	  const reason = poll.deadlineMs && Date.now() >= poll.deadlineMs ? '已到截止时间' : '发起人已关闭';
15	  return `<p class="closed" role="status">投票已关闭（${htmlEscape(reason)}）。你仍可查看结果。</p>`;
16	}
17	
18	// 创建页
19	function createPage() {
20	  return layout('创建投票', `
21	<h1>创建快速投票</h1>
22	<form id="createForm">
23	  <label>标题 <input name="title" maxlength="200" required></label>
24	  <fieldset><legend>选项（2..20）</legend>
25	    <input name="option" placeholder="选项 1"><input name="option" placeholder="选项 2">
26	    <input name="option" placeholder="选项 3"><input name="option" placeholder="选项 4">
27	  </fieldset>
28	  <label><input type="radio" name="mode" value="single" checked>单选</label>
29	  <label><input type="radio" name="mode" value="multiple">多选</label>
30	  <label>截止时间（可选）<input type="datetime-local" name="deadline"></label>
31	  <button type="submit">创建</button>
32	</form>
33	<div id="out"></div>
34	<script src="/public/create.js"></script>`);
35	}
36	
37	// 投票页（PC-05 软限脚本 / PC-09 关闭态 / PC-15 转义）
38	function votePage(poll) {
39	  const isClosed = poll.status === 'closed' || (poll.deadlineMs && Date.now() >= poll.deadlineMs);
40	  const inputType = poll.mode === 'single' ? 'radio' : 'checkbox';
41	  const opts = poll.options.map((o) =>
42	    `<label><input type="${inputType}" name="opt" value="${htmlEscape(o.id)}"> ${htmlEscape(o.text)}</label>`).join('');
43	  const voteControls = isClosed ? '' :
44	    `<form id="voteForm"><fieldset>${opts}</fieldset><button type="submit">投票</button></form>`;
45	  const banner = isClosed ? closedBanner(poll) : '';
46	  const bootstrap = `<script>window.__POLL__=${jsonForScript({ pollId: poll.pollId, mode: poll.mode, closed: isClosed })};</script>`;
47	  // PC-05 软限：同浏览器已投过 → 直接跳结果视图。key 作用域 origin+pollId。
48	  const softLimit = `<script>
49	(function(){var p=window.__POLL__;var k='voted:'+location.origin+':'+p.pollId;
50	if(localStorage.getItem(k)){location.replace('/r/'+p.pollId);}})();
51	</script>`;
52	  return layout(poll.title, `
53	<h1>${htmlEscape(poll.title)}</h1>
54	${banner}
55	${voteControls}
56	<p><a href="/r/${htmlEscape(poll.pollId)}">查看结果</a></p>
57	${bootstrap}${softLimit}
58	<script src="/public/poll.js"></script>`);
59	}
60	
61	// 结果页（PC-06 轮询 / PC-15）
62	function resultPage(poll) {
63	  const rows = poll.options.map((o) =>
64	    `<li data-id="${htmlEscape(o.id)}"><span class="t"></span> <b class="c">${o.count}</b></li>`).join('');
65	  const closed = poll.status === 'closed' || (poll.deadlineMs && Date.now() >= poll.deadlineMs);
66	  const banner = closed ? closedBanner(poll) : '';
67	  const bootstrap = `<script>window.__RESULT__=${jsonForScript({ pollId: poll.pollId, intervalMs: POLL_INTERVAL_MS })};</script>`;
68	  const poller = `<script>
69	(function(){var r=window.__RESULT__;
70	function esc(s){return s;}
71	function render(d){document.getElementById('title').textContent=d.title;
72	document.getElementById('total').textContent=d.total;
73	var byId={};d.options.forEach(function(o){byId[o.id]=o;});
74	document.querySelectorAll('#list li').forEach(function(li){var o=byId[li.getAttribute('data-id')];
75	if(o){li.querySelector('.t').textContent=o.text;li.querySelector('.c').textContent=o.count;}});}
76	function pull(){fetch('/api/polls/'+r.pollId+'/results').then(function(x){return x.json();}).then(render);}
77	pull();setInterval(pull, ${POLL_INTERVAL_MS});})();
78	</script>`;
79	  return layout(poll.title, `
80	<h1 id="title">${htmlEscape(poll.title)}</h1>
81	${banner}
82	<p>总票数：<b id="total">${poll.total != null ? poll.total : ''}</b></p>
83	<ul id="list">${rows}</ul>
84	${bootstrap}${poller}`);
85	}
86	
87	// 管理页
88	function adminPage(poll, key) {
89	  const closed = poll.status === 'closed' || (poll.deadlineMs && Date.now() >= poll.deadlineMs);
90	  return layout('管理 · ' + poll.title, `
91	<h1>管理：${htmlEscape(poll.title)}</h1>
92	<p><a href="/r/${htmlEscape(poll.pollId)}">结果</a> · 投票链接 <code>/p/${htmlEscape(poll.pollId)}</code></p>
93	${closed ? closedBanner(poll) : `<button id="closeBtn">关闭投票</button>`}
94	<script>window.__ADMIN__=${jsonForScript({ pollId: poll.pollId, key })};</script>
95	<script src="/public/admin.js"></script>`);
96	}
97	
98	module.exports = { POLL_INTERVAL_MS, layout, createPage, votePage, resultPage, adminPage };

// 创建页：收集标题/选项/模式/截止 → POST；成功后展示两条链接。
(function () {
  var form = document.getElementById('createForm');
  form.addEventListener('submit', function (e) {
    e.preventDefault();
    var title = form.querySelector('input[name=title]').value;
    var options = Array.prototype.slice.call(form.querySelectorAll('input[name=option]'))
      .map(function (i) { return i.value; }).filter(function (v) { return v.trim().length; });
    var mode = form.querySelector('input[name=mode]:checked').value;
    var dl = form.querySelector('input[name=deadline]').value;
    var body = { title: title, options: options, mode: mode };
    if (dl) body.deadline = new Date(dl).toISOString();
    fetch('/api/polls', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify(body) })
      .then(function (res) { return res.json().then(function (b) { return { ok: res.ok, b: b }; }); })
      .then(function (r) {
        var out = document.getElementById('out');
        if (!r.ok) { out.textContent = '创建失败：' + (r.b.error || ''); return; }
        out.innerHTML = '';
        var a1 = document.createElement('p'); a1.id='voteUrl'; a1.textContent = r.b.voteUrl;
        var a2 = document.createElement('p'); a2.id='adminUrl'; a2.textContent = r.b.adminUrl;
        var lbl=document.createElement('p'); lbl.textContent='投票链接与管理链接（自己保管）：';
        out.appendChild(lbl); out.appendChild(a1); out.appendChild(a2);
      });
  });
})();

// 管理页：凭 key 关闭投票。
(function () {
  var a = window.__ADMIN__;
  var btn = document.getElementById('closeBtn');
  if (!btn) return;
  btn.addEventListener('click', function () {
    fetch('/api/polls/' + a.pollId + '/close', {
      method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ adminKey: a.key })
    }).then(function (res) {
      if (res.ok) location.reload(); else res.json().then(function (b) { alert('关闭失败：' + (b.error || res.status)); });
    });
  });
})();

  1	'use strict';
  2	// HTTP 服务 + 路由（单进程）。vote/close 走 per-poll 队列；durable 成功后才 2xx。
  3	const http = require('node:http');
  4	const crypto = require('node:crypto');
  5	const fs = require('node:fs');
  6	const path = require('node:path');
  7	
  8	const ids = require('./ids');
  9	const store = require('./store');
 10	const { runExclusive } = require('./queue');
 11	const { validateCreate, validateVote } = require('./validate');
 12	const views = require('./views');
 13	
 14	function send(res, code, body, type = 'application/json') {
 15	  const payload = type === 'application/json' ? JSON.stringify(body) : body;
 16	  res.writeHead(code, { 'content-type': type + '; charset=utf-8' });
 17	  res.end(payload);
 18	}
 19	function sendJson(res, code, obj) { send(res, code, obj, 'application/json'); }
 20	function sendHtml(res, code, html) { send(res, code, html, 'text/html'); }
 21	
 22	async function readBody(req) {
 23	  const chunks = [];
 24	  for await (const c of req) chunks.push(c);
 25	  if (!chunks.length) return {};
 26	  try { return JSON.parse(Buffer.concat(chunks).toString('utf8')); }
 27	  catch { return Symbol.for('bad-json'); }
 28	}
 29	
 30	// 关闭时的截止/状态判定（进入临界区时求值）
 31	function effectiveClosed(poll) {
 32	  return poll.status === 'closed' || (poll.deadlineMs != null && Date.now() >= poll.deadlineMs);
 33	}
 34	
 35	function resultsView(poll) {
 36	  return {
 37	    title: poll.title,
 38	    options: poll.options.map((o) => ({ id: o.id, text: o.text, count: poll.counts[o.id] })),
 39	    total: Object.values(poll.counts).reduce((a, b) => a + b, 0),
 40	    status: effectiveClosed(poll) ? 'closed' : 'open',
 41	    deadline: poll.deadlineMs,
 42	  };
 43	}
 44	
 45	function safeKeyEqual(a, b) {
 46	  const ba = Buffer.from(String(a));
 47	  const bb = Buffer.from(String(b));
 48	  if (ba.length !== bb.length) return false;
 49	  return crypto.timingSafeEqual(ba, bb);
 50	}
 51	
 52	function createServer(opts = {}) {
 53	  const dataDir = opts.dataDir || path.join(process.cwd(), 'data', 'polls');
 54	  const hooks = opts._hooks || {};
 55	  fs.mkdirSync(dataDir, { recursive: true });
 56	
 57	  return http.createServer(async (req, res) => {
 58	    try {
 59	      const url = new URL(req.url, 'http://localhost');
 60	      const origin = 'http://' + (req.headers.host || 'localhost');
 61	      const parts = url.pathname.split('/').filter(Boolean);
 62	      const method = req.method;
 63	
 64	      // 静态前端
 65	      if (method === 'GET' && parts[0] === 'public') {
 66	        const f = path.join(__dirname, '..', 'public', path.basename(url.pathname));
 67	        if (fs.existsSync(f)) return send(res, 200, fs.readFileSync(f, 'utf8'), 'application/javascript');
 68	        return send(res, 404, 'not found', 'text/plain');
 69	      }
 70	
 71	      // 创建页
 72	      if (method === 'GET' && parts.length === 0) return sendHtml(res, 200, views.createPage());
 73	
 74	      // 页面：投票 / 结果 / 管理（未知 pollId → 404）
 75	      if (method === 'GET' && parts[0] === 'p' && parts[1]) {
 76	        const poll = store.read(dataDir, parts[1]);
 77	        if (!poll) return sendHtml(res, 404, views.layout('未找到', '<h1>投票不存在</h1>'));
 78	        return sendHtml(res, 200, views.votePage(poll));
 79	      }
 80	      if (method === 'GET' && parts[0] === 'r' && parts[1]) {
 81	        const poll = store.read(dataDir, parts[1]);
 82	        if (!poll) return sendHtml(res, 404, views.layout('未找到', '<h1>投票不存在</h1>'));
 83	        return sendHtml(res, 200, views.resultPage({ ...poll, ...resultsView(poll) }));
 84	      }
 85	      if (method === 'GET' && parts[0] === 'admin' && parts[1]) {
 86	        const poll = store.read(dataDir, parts[1]);
 87	        if (!poll) return sendHtml(res, 404, views.layout('未找到', '<h1>投票不存在</h1>'));
 88	        const key = url.searchParams.get('key') || '';
 89	        if (!safeKeyEqual(key, poll.adminKey)) return sendHtml(res, 403, views.layout('无权限', '<h1>管理密钥无效</h1>'));
 90	        return sendHtml(res, 200, views.adminPage(poll, key));
 91	      }
 92	
 93	      // API: 创建
 94	      if (method === 'POST' && parts[0] === 'api' && parts[1] === 'polls' && parts.length === 2) {
 95	        const body = await readBody(req);
 96	        if (body === Symbol.for('bad-json')) return sendJson(res, 400, { error: 'invalid json' });
 97	        const v = validateCreate(body);
 98	        if (!v.ok) return sendJson(res, v.code, { error: v.error });
 99	        const pollId = ids.newPollId();
100	        const adminKey = ids.newAdminKey();
101	        const options = v.value.options.map((text, i) => ({ id: 'opt-' + i, text }));
102	        const counts = {};
103	        options.forEach((o) => { counts[o.id] = 0; });
104	        const poll = { pollId, title: v.value.title, options, mode: v.value.mode, deadlineMs: v.value.deadlineMs, status: 'open', counts, adminKey };
105	        try {
106	          store.save(dataDir, poll, hooks); // durable 成功后才继续
107	        } catch (e) {
108	          return sendJson(res, 500, { error: 'persist failed' }); // 不留半个记录（原子写已保证）
109	        }
110	        return sendJson(res, 201, {
111	          pollId, adminKey,
112	          voteUrl: `${origin}/p/${pollId}`,
113	          adminUrl: `${origin}/admin/${pollId}?key=${adminKey}`,
114	          resultUrl: `${origin}/r/${pollId}`,
115	        });
116	      }
117	
118	      // API: 投票
119	      if (method === 'POST' && parts[0] === 'api' && parts[1] === 'polls' && parts[3] === 'vote') {
120	        const id = parts[2];
121	        const body = await readBody(req);
122	        if (body === Symbol.for('bad-json')) return sendJson(res, 400, { error: 'invalid json' });
123	        if (!store.exists(dataDir, id)) return sendJson(res, 404, { error: 'poll not found' });
124	        const outcome = await runExclusive(id, async () => {
125	          const poll = store.read(dataDir, id);           // 临界区内读最新
126	          if (!poll) return { code: 404, error: 'poll not found' };
127	          if (effectiveClosed(poll)) return { code: 409, error: 'poll is closed' };
128	          const v = validateVote(poll, body);
129	          if (!v.ok) return { code: v.code, error: v.error };
130	          for (const oid of v.value.optionIds) poll.counts[oid] += 1;
131	          store.save(dataDir, poll, hooks);               // 失败则抛错 → 计数不落盘
132	          return { code: 200, results: resultsView(poll) };
133	        }).catch((e) => ({ code: 500, error: 'persist failed' }));
134	        if (outcome.code === 200) return sendJson(res, 200, { ok: true, resultUrl: `${origin}/r/${id}`, results: outcome.results });
135	        return sendJson(res, outcome.code, { error: outcome.error });
136	      }
137	
138	      // API: 结果
139	      if (method === 'GET' && parts[0] === 'api' && parts[1] === 'polls' && parts[3] === 'results') {
140	        const poll = store.read(dataDir, parts[2]);
141	        if (!poll) return sendJson(res, 404, { error: 'poll not found' });
142	        return sendJson(res, 200, resultsView(poll));
143	      }
144	
145	      // API: 关闭
146	      if (method === 'POST' && parts[0] === 'api' && parts[1] === 'polls' && parts[3] === 'close') {
147	        const id = parts[2];
148	        const body = await readBody(req);
149	        if (body === Symbol.for('bad-json')) return sendJson(res, 400, { error: 'invalid json' });
150	        if (!store.exists(dataDir, id)) return sendJson(res, 404, { error: 'poll not found' });
151	        const outcome = await runExclusive(id, async () => {
152	          const poll = store.read(dataDir, id);
153	          if (!poll) return { code: 404, error: 'poll not found' };
154	          if (!safeKeyEqual(body && body.adminKey, poll.adminKey)) return { code: 403, error: 'invalid admin key' };
155	          if (poll.status === 'closed') return { code: 200, ok: true };
156	          poll.status = 'closed';
157	          store.save(dataDir, poll, hooks);
158	          return { code: 200, ok: true };
159	        }).catch(() => ({ code: 500, error: 'persist failed' }));
160	        return sendJson(res, outcome.code, outcome.ok ? { ok: true } : { error: outcome.error });
161	      }
162	
163	      return send(res, 404, 'not found', 'text/plain');
164	    } catch (e) {
165	      try { sendJson(res, 500, { error: 'internal error' }); } catch { /* headers 已发 */ }
166	    }
167	  });
168	}
169	
170	module.exports = { createServer, resultsView, effectiveClosed };
